  /** Whether the claim is overdue: open and not deferred, with its due-by plus the grace days of its
   *  person's grade before the sheet's today. */
  private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
      return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null
              && LateCharge.lateFrom(claim, grace).isBefore(today);
  }

  /** What counts toward what is claimed: as counts decides, except that a hold (the person's or the
   *  claim's) does not take a claim out of it. */
  private static boolean countsClaimed(Person person, Claim claim, LocalDate today) {
      return claim.getStatus() == ClaimStatus.SETTLED
              || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                      && (claim.isBound() || !person.isRetiredBy(today)));
  }

  /** Only open (PENDING included) and settled claims count toward what is claimed and due; a person's
   *  open claims dated within one of their holds, or all of them once their retirement date is reached,
   *  and a held claim do not, unless a statement binds them; nor does a
   *  claim deferred on the sheet's today. */
  private static boolean counts(Person person, Claim claim, LocalDate today) {
      return claim.getStatus() == ClaimStatus.SETTLED
              || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                      && (claim.isBound() || !(claim.isHeld() || person.isLeftOut(claim.getDate(), today))));
  }

  /** The claim's figure, as ClaimService.figure works it out: the settled due, else the stated due
   *  (PENDING included), else the rate figure at the grade's rate in force on its date (the sheet's, else its nearest parent's) of the
   *  versions that apply to the claim, rounded as the claim rounds,
   *  before any late charge and floor; null when that is n/a. */
  private static BigDecimal figure(Claim claim, List<List<Rate>> gradeRates, RoundingMode rounding) {
      if (claim.getSettledDue() != null) return claim.getSettledDue();
      if (claim.isBound()) return claim.getStatedDue();
      Rate rate = Rate.inForceInherited(gradeRates, claim.getDate());
      if (rate == null) return null;
      return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2, rounding);
  return money(this.personCarriedCents().get(personId)?.get(periodId) ?? 0);
}

/** The person's due-total for the period, with two decimals. */
protected personPeriodDue(personId: number, periodId: number): string {
  return money(this.personPeriodCents().get(personId)?.get(periodId) ?? 0);
}

/** Whether the claim counts in the live totals: open (PENDING included) and settled claims do,
 *  except open claims dated within a hold of their person, or of a person whose retirement date the
 *  sheet's today has reached, and held open claims, that no statement binds, and claims
 *  deferred on the sheet's today. */
private countsLive(claim: ClaimView): boolean {
  return counts(claim) && !isDeferred(claim, this.session.sheet()?.today) && !(isOpen(claim) && !isBound(claim)
    && this.leftOut(claim));
}

/** Whether the claim, open and unbound, leaves the live totals: held itself, dated within a hold of its
 *  person, or its person's retirement date reached by the sheet's today. */
private leftOut(claim: ClaimView): boolean {
  const retiredFrom = this.retiredFromById().get(claim.personId) ?? null;
  const today = this.session.sheet()?.today;
  return claim.held || heldOn(this.holdsById().get(claim.personId) ?? [], claim.date)
    || (retiredFrom !== null && today !== undefined && retiredFrom <= today);
}

/** Whether the claim's person's retirement date is reached by the sheet's today. */
private retired(claim: ClaimView): boolean {
  const retiredFrom = this.retiredFromById().get(claim.personId) ?? null;
  const today = this.session.sheet()?.today;
  return retiredFrom !== null && today !== undefined && retiredFrom <= today;
}

/** Whether the claim counts in a period ending on `end`: as countsLive decides, but by the status
 *  its log records at the end of that day (none when added after it); deferral is as today, and a hold
 *  only leaves out a claim that is still open now, as holds touch only live claims. */
private countsAt(claim: ClaimView, end: string): boolean {
  const status = statusAsOf(claim, end);
  if (status === null) return false;
  const then: ClaimView = { ...claim, status };
  return counts(then) && !isDeferred(claim, this.session.sheet()?.today) && !(isOpen(then) && isOpen(claim) && !isBound(then)
    && this.leftOut(claim));
}

/** The person's patrons, each as <name> <share>, sorted by name, comma and space separated. */
protected patronNames(person: PersonView): string {
  const byId = new Map(this.people().map((p) => [p.id, p]));
  return sharesOf(person.patronIds).map(([id, share]) => [byId.get(id), share] as const)
    .filter((e): e is readonly [PersonView, bigint] => e[0] !== undefined)
    .sort(([a], [b]) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .map(([p, share]) => `${this.shownName(p)} ${money(Number(share))}`).join(', ');
}

/** The person's name as the screen shows it, with their grade in force on the sheet's today. */
protected shownName(person: PersonView): string {
